def func(arr,k):
    # Create a dictionary to store frequency of each number
    freq = {}
    for sublist in arr:
        for num in sublist:
            if num in freq:
                freq[num] += 1
            else:
                freq[num] = 1

    # Use a min-heap to keep track of the top k frequent numbers
    min_heap = []
    for num, count in freq.items():
        if len(min_heap) < k:
            heapq.heappush(min_heap, (count, num))
        elif count > min_heap[0][0]:
            heapq.heappop(min_heap)
            heapq.heappush(min_heap, (count, num))

    # Extract the numbers from the heap
    result = [num for _, num in min_heap]
    return result[::-1]  # Return the result in descending order
```
