def get_total_number_of_sequences(n, m):
    # Initialize a list to store the number of sequences ending with each value from 0 to m
    dp = [0] * (m + 1)

    # There's exactly one way to form a sequence of length 1 starting with any number from 0 to m
    for i in range(m + 1):
        dp[i] = 1

    # Fill the dp array for sequences of length 2 to n
    for length in range(2, n + 1):
        for current in range(m, -1, -1):
            # Update the dp array for sequences of length 'length' ending with 'current'
            dp[current] += dp[max(current // 2, 0)]

    # The total number of sequences of length n is the sum of sequences ending with numbers from 0 to m
    return sum(dp)
```

