def max_sum(arr, n):
    # Initialize the dp array where dp[i] stores the maximum sum of bi-tonic sub-sequence ending at arr[i]
    dp = [arr[i] for i in range(n)]

    # Compute the maximum sum of bi-tonic sub-sequence ending at each element
    for i in range(1, n):
        for j in range(i):
            if (arr[j] < arr[i]) and (dp[i] < dp[j] + arr[i]):
                dp[i] = dp[j] + arr[i]

    # Find the maximum value in dp array which represents the maximum sum of bi-tonic sub-sequence
    return max(dp)
